                (() => { const modal = document.getElementById('agenda-editor'); if (!modal) return; document.querySelectorAll('[data-agenda-open]').forEach((button) => button.addEventListener('click', () => modal.showModal())); document.querySelectorAll('[data-agenda-close]').forEach((button) => button.addEventListener('click', () => modal.close())); modal.addEventListener('click', (event) => { if (event.target === modal) modal.close(); }); const assignment = modal.querySelector('[data-agenda-assignment]'); const section = modal.querySelector('[data-agenda-section]'); assignment?.addEventListener('change', () => { section.value = assignment.selectedOptions[0]?.dataset.section || ''; }); modal.querySelectorAll('[data-wrap]').forEach((button) => button.addEventListener('click', () => { const editor = modal.querySelector('textarea[name="content"]'); const start = editor.selectionStart, end = editor.selectionEnd, selected = editor.value.slice(start, end) || 'text'; const wrapper = button.dataset.wrap === 'bold' ? ['**', '**'] : button.dataset.wrap === 'italic' ? ['*', '*'] : button.dataset.wrap === 'list' ? ['- ', ''] : ['[', '](https://)']; editor.setRangeText(wrapper[0] + selected + wrapper[1], start, end, 'end'); editor.focus(); })); })();
